"""Verify seven original dndscv roles and draft scoped reviews without changing the current catalog."""
import argparse,gzip,hashlib,json,re,xml.etree.ElementTree as ET
from pathlib import Path
from setup_deseq2_reference import ROOT,pin,save
from collect_omics_review import paragraphs

SPECS=[
 ('P036',74,[75,76,77,78,79],None,'coverage-adjusted-panel-selection','Estimated positive and negative selection using a bespoke coding reference for the sequencing panel, with the192-channel opportunity matrix adjusted by per-gene median coverage for each sample, tissue and cohort and zero coverage at blacklisted sites.','The coverage-adjusted reference and panel construction are caller inputs, not standard unweighted opportunities or a generic single-gene coverage multiplier. Separate display filters use observed and expected mutation counts (paragraphs75–79); do not apply them silently to inference. The package version, function arguments and precise reference object are not provided.'),
 ('P042',43,[44,45,46],None,'IntOGen-component-and-driver-ratios','Used dNdSCV as one of seven components in IntOGen2023 for protein-coding driver discovery, and used its missense and nonsense selection ratios for a separate driver-role classification.','IntOGen2023 is the wrapper version, not a dndscv release. Schulze voting, weighted Stouffer consensus, CGC weighting and the reported driver-role distance classification are separate downstream methods. The standalone source workflow does not reconstruct the seven-method consensus; the dndscv version, arguments and exact distance expression remain source-specific.'),
 ('P056',44,[],'0.1.0','mouse-panel-selection','Identified genes under positive or negative selection using a supplied mm10_Ens96_dNdScv.rda reference, with both per-gene-per-sample and coding-per-sample mutation limits set to Inf.','The paper reports0.1.0; the resolved upstream source labels itself0.0.1.0. Do not normalize these labels or infer an exact paper commit. Trerf1 was absent from the RefCDS and Dlg2/Rit1 were outside the baits; preserve the caller gene universe and custom reference instead of silently removing genes or selecting a human default.'),
 ('P111',47,[49],None,'normal-esophagus-selection','Applied the previously described dN/dS analysis using dNdScv; the statistics paragraph used global q<0.01 and a separate filter for genes with no synonymous mutations and few nonsynonymous mutations.','The package version, reference, functions and fitting settings are unspecified. The percentage-mutant-tissue calculation is separate. Paragraph49 says eight or fewer mutations in its filtering statement but later says at least eight; retain that wording ambiguity and require an explicit downstream rule instead of silently choosing an8/9 boundary. Statistical reliability and negative-selection power are not established by software execution.'),
 ('P146',58,[24,25],'0.0.1.0','gene-and-gene-set-selection','Estimated gene-level dN/dS across lesional and nonlesional skin and global selection for11 predefined gene sets; the figure description identifies a pentanucleotide model for pathway-level estimates.','The version label does not identify a source commit. Standard192-channel trinucleotide dndscv or genesetdnds is not evidence of the stated pentanucleotide pathway model; that reference/model and its preprocessing require separate provenance. Lesional/nonlesional subset fits and cell-fraction calculations remain separate. Do not infer geneset membership, fitting arguments or full-paper equivalence.'),
 ('P148',49,[],None,'complementary-gene-selection','Used dNdScv alongside activation-bias and inactivation-bias methods to find significantly mutated genes, admitting a gene if any method yielded q<0.1.','The Fisher tests, hotspot definition including the5-bp neighborhood, tumor-suppressor assignment and forced activation-bias P=1 belong to the separate bias methods. Do not implement those rules as dndscv semantics or infer a combined calibration. The dndscv version, reference and fitting arguments are unspecified.'),
 ('P165',65,[],None,'clone-based-targeted-mouse-selection','Applied dNdScv to independent-clone mutation counts using a custom GRCm39 reference whose trinucleotide substitution-consequence opportunities were restricted to the targeted genomic regions.','The paper says latest version without identifying a release or commit. Preserve clone-defined events, the mouse assembly, targeted reference and supplied opportunity matrix; do not substitute read counts, spot counts, a human default or an untargeted reference. Function arguments and reference-generation details beyond the stated construction remain unspecified.')
]


def main():
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--out',required=True,type=Path);a=p.parse_args();out=a.out.resolve();assert out.is_relative_to(ROOT/'build/literature-review/dndscv-runtime') and not out.exists();out.mkdir();papers=json.loads((ROOT/'docs/literature/omics-2023-2026/papers.json').read_bytes());drafts=[];sources={}
    for pid,index,support,version,context,summary,scope in SPECS:
        paper=next(p for p in papers if p['paper_id']==pid);raw=gzip.decompress((ROOT/'build/literature-review/xml'/(paper['pmcid']+'.xml.gz')).read_bytes());assert hashlib.sha256(raw).hexdigest()==paper['xml_sha256'];root=ET.fromstring(raw);assert next(e.text for e in root.findall('front/article-meta/article-id') if e.get('pub-id-type')=='doi').lower()==paper['doi'].lower();ps=paragraphs(root);by={r['paragraph_index']:r for r in ps};primary=by[index];obs=next(t for t in paper['tools'] if t['tool_id']=='dndscv');sha=hashlib.sha256(primary['text'].encode('utf8')).hexdigest();assert obs['evidence_paragraph_index']==index and obs['evidence_paragraph_sha256']==sha and re.search('dndscv',primary['text'],re.I)
        supporting=[dict(paragraph_index=i,section=by[i]['section'],paragraph_sha256=hashlib.sha256(by[i]['text'].encode('utf8')).hexdigest()) for i in support];review=dict(pmcid=paper['pmcid'],doi=paper['doi'],tool_id='dndscv',evidence_paragraph_sha256=sha,use_summary=summary,implementation_scope_note=scope,version_reported_near_name=version,usage_context=context,supporting_evidence=supporting);drafts.append(dict(paper_id=pid,primary_paragraph=index,section=primary['section'],review=review,fulltext_url=paper['fulltext_url'] if 'fulltext_url' in paper else 'https://pmc.ncbi.nlm.nih.gov/articles/'+paper['pmcid']+'/',xml_sha256=paper['xml_sha256']));sources[pid]=dict(primary=primary,supporting=[by[i] for i in support]);(out/(paper['pmcid']+'.xml.gz')).write_bytes(gzip.compress(raw,mtime=0))
    assert len(drafts)==7 and not any(r['tool_id']=='dndscv' for r in json.loads((ROOT/'tools/literature/reviewed-uses.json').read_bytes())['reviews']);save(out/'draft-reviews.json',drafts);save(out/'source-paragraphs.json',sources);save(out/'COMPLETED.json',dict(status='verified-seven-dndscv-primary-role-drafts-not-applied',roles=7,supporting_paragraphs=sum(len(d['review']['supporting_evidence']) for d in drafts),source_pins={Path(__file__).resolve().relative_to(ROOT).as_posix():pin(Path(__file__))},drafts=pin(out/'draft-reviews.json'),paragraphs=pin(out/'source-paragraphs.json'),applied=False,analysis_admitted=False,implementation_credit=False,current_catalog_unchanged=True,whole_goal_complete=False));print('Verified7 primary roles; retained custom coverage/panel/mouse contexts, wrapper distinctions, version and filtering ambiguities; drafts unapplied')


if __name__=='__main__':
    if not __debug__:raise RuntimeError('Never disable paper/source checks')
    main()
